// DecodeSwitchKeyRequest returns a decoder for requests sent to the
// orgEncryption switchKey endpoint.
func DecodeSwitchKeyRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*orgencryption.SwitchKeyPayload, error) {
	return func(r *http.Request) (*orgencryption.SwitchKeyPayload, error) {
		var payload *orgencryption.SwitchKeyPayload
		var (
			body SwitchKeyRequestBody
			err  error
		)
		err = decoder(r).Decode(&body)
		if err != nil {
			if errors.Is(err, io.EOF) {
				return payload, goa.MissingPayloadError()
			}
			var gerr *goa.ServiceError
			if errors.As(err, &gerr) {
				return payload, gerr
			}
			return payload, goa.DecodePayloadError(err.Error())
		}
		err = ValidateSwitchKeyRequestBody(&body)
		if err != nil {
			return payload, err
		}

		var (
			sessionToken *string
		)
		sessionTokenRaw := r.Header.Get("Gram-Session")
		if sessionTokenRaw != "" {
			sessionToken = &sessionTokenRaw
		}
		payload = NewSwitchKeyPayload(&body, sessionToken)
		if payload.SessionToken != nil {
			if strings.Contains(*payload.SessionToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.SessionToken, " ", 2)[1]
				payload.SessionToken = &cred
			}
		}

		return payload, nil
	}
}

